#include "robotka.h"\n#include "ulohy.h"\n#include <Wire.h>\n#include <Adafruit_VL53L0X.h>\n\nbyte Bbutton1 = 34;\nbyte Bbutton2 = 35;\n\n// deklarace instanci laseru\nAdafruit_VL53L0X lox_front = Adafruit_VL53L0X();\nAdafruit_VL53L0X lox_back = Adafruit_VL53L0X();\nAdafruit_TCS34725 tcs = Adafruit_TCS34725(TCS34725_INTEGRATIONTIME_50MS, TCS34725_GAIN_1X);\n\nvoid trap() {\n    Serial.println("trap\n");\n    while (1)\n        ;\n}\nvoid test_batery(){\n    printf("batery percent: %u\n", rkBatteryPercent());\n    printf("batery voltage: %u\n", rkBatteryVoltageMv()/1000);\n}\nvoid configurating(){\n    Serial.begin(115200);\n    rkConfig cfg;\n    rkSetup(cfg);\n    pinMode(14, PULLUP);\n    pinMode(26, PULLUP);\n    // Spust I2C sbernice\n    // Wire bude na pinech 14,26\n    Wire.begin(14, 26, 400000);\n    delay(100);\n    Wire.setTimeOut(1);\n    // Wire1 bude na pinech 21,22 (pro lasery)\n\n    static const uint8_t TCS_SDA_pin = 21;\n    static const uint8_t TCS_SCL_pin = 22;\n\n    pinMode(TCS_SDA_pin, PULLUP);\n    pinMode(TCS_SCL_pin, PULLUP);\n    Wire1.begin(TCS_SDA_pin, TCS_SCL_pin, 100000);\n    Wire1.setTimeOut(1); // from example\n\n    // Inicializuj dva laserove senzory na Wire (piny 14/26)\n    rk_laser_init("front", Wire, lox_front, 1, 0x29);\n    rk_laser_init("back",  Wire, lox_back,  2, 0x29);\n\n    // Initialize the color sensor with a unique name and the I2C bus (na Wire1)\n    rkColorSensorInit("color", Wire1, tcs);\n    \n    printf("Starting main loop\n");\n    //start tlacitko pro kalibraci klepet\n\n    rkLedBlue(false);\n    rkLedGreen(false);\n    rkLedYellow(false);\n    rkLedRed(false);\n    test_batery();\n    zavrit_klepeto();\n}\n\nenum RobotButton {\n    NONE,\n    UP_VYHREJ,\n    OFF_MEDVED,\n    DOWN_KULICKY,\n    RIGHT_BLUDISTE,\n    LEFT_SLALOM,\n    ON_SPRINT,\n    BUTTON1_KOMBINACE1,\n    BUTTON2_KOMBINACE2\n};\n\nRobotButton getPressed() {\n    if (rkButtonUp()) return UP_VYHREJ;\n    if (rkButtonOff()) return OFF_MEDVED;\n    if (rkButtonDown()) return DOWN_KULICKY;\n    if (rkButtonRight()) return RIGHT_BLUDISTE;\n    if (rkButtonLeft()) return LEFT_SLALOM;\n    if (rkButtonOn()) return ON_SPRINT;\n    if (digitalRead(Bbutton1) == LOW) return BUTTON1_KOMBINACE1;\n    if (digitalRead(Bbutton2) == LOW) return BUTTON2_KOMBINACE2;\n    return NONE;\n}\n\nvoid setup() {\n    configurating();\n}\n\nvoid loop() {\n    rkLedBlue(false);\n    rkLedGreen(false);\n    rkLedYellow(false);\n    rkLedRed(false);\n\n    switch(getPressed()) {\n        case UP_VYHREJ:\n            rkLedGreen(true); // Zelená pro výhru\n            delay(10000);\n            // Kombinace úkolů pro "vyhrej"\n            sprint_m_d(); \n            rkBuzzerSet(true);\n            delay(200);\n            rkBuzzerSet(false);\n            delay(10000);\n            slalom(true); \n            delay(10000);\n            bludiste();\n            srovnej_se_v_pravo();\n            turn_on_spot_left(90, 50);\n            delay(100);\n            back_buttons(40);\n            delay(100);\n            forward_acc(od_steny_na_stred_pole, 50);\n            delay(10000);\n            medved();\n            delay(10000);\n            kulicky();\n            break;\n\n        case OFF_MEDVED:\n            rkLedRed(true); // Červená pro medvěda\n            delay(10000);\n            medved();\n            break;\n\n        case DOWN_KULICKY:\n            rkLedBlue(true); // Modrá pro kuličky\n            delay(1000);\n            kulicky();\n            break;\n            \n        case RIGHT_BLUDISTE:\n            rkLedYellow(true); // Žlutá pro bludiště\n            delay(1000);\n            bludiste();\n            break;\n            \n        case LEFT_SLALOM:\n            rkLedRed(true);\n            rkLedYellow(true); // Oranžová pro slalom\n            delay(1000);\n            slalom(true);\n            \n            break;\n            \n        case ON_SPRINT:\n            rkLedBlue(true);\n            rkLedRed(true); // Fialová pro sprint\n            delay(1000);\n            sprint_cara();\n            break;\n            \n        case BUTTON1_KOMBINACE1:\n            rkLedGreen(true);\n            rkLedYellow(true); // Zeleno-žlutá pro kombinaci 1\n            delay(1000);\n\n            while(true){\n                delay(1000);\n\n                bool a = cervena();\n                \n\n            }\n        \n            delay(1000);\n            \n            break;\n            \n        case BUTTON2_KOMBINACE2:\n            rkLedRed(true);\n            rkLedGreen(true);\n            rkLedBlue(true);\n            rkLedYellow(true); // Bílá (všechny barvy) pro kombinaci 2\n            delay(1000);\n            srovnej_na_caru();\n            break;\n        \n        case NONE:\n            break;\n    }\n    delay(100);\n}